#!/bin/bash
# Regenerates translation/SYMBOLS.md from `nm -D` on the built C and Rust
# shared objects.  Nothing here is hand-maintained.
ROOT="$(cd "$(dirname "$0")" && pwd)"
OUT="$ROOT/translation/SYMBOLS.md"

csyms() { # $1=be $2=th $3=sp
  nm -D --defined-only \
    "$ROOT/cbuild/$1_$2_$3/app/libsphincs_core.so" \
    "$ROOT/cbuild/$1_$2_$3/app/libsphincs_core_det.so" \
    "$ROOT/cbuild/$1_$2_$3/lib/$1/lib$1.so" 2>/dev/null \
    | awk 'NF==3{print $3" "$2}' | grep -v '^_' | sort -u
}
rsyms() {
  nm -D --defined-only "$ROOT/rustlib/libsphincs_plus_$1_$2_$3.so" \
    | awk 'NF==3{print $3}' | grep -v '^_' | sort -u
}

{
cat <<'HDR'
# SYMBOLS.md — C ⇄ Rust dynamic-symbol parity

Generated by `./gen_symbols.sh` from `nm -D --defined-only` on the built shared
objects.  Not hand-maintained.

## What the C build produces

For one `(HASH_BACKEND, THASH, SECPAR)` configuration CMake emits three shared
objects (plus the `driver` executable):

| C shared object | sources | notes |
|---|---|---|
| `app/libsphincs_core.so` | `address.c fors.c merkle.c sign.c utils.c utilsx1.c wots.c wotsx1.c` + `randombytes.c` | `randombytes` reads `/dev/urandom`; `void` return |
| `app/libsphincs_core_det.so` | the same object files + `rng.c` | `randombytes` is the NIST AES-256-CTR-DRBG; `int` return |
| `lib/<be>/lib<be>.so` | the backend's `<be>.c hash_<be>.c thash_<be>_<THASH>.c` (+ `utils.c` for sha2/blake) | provides `SPX_thash`, `SPX_prf_addr`, … |

The Rust crate is a single `cdylib` (`libsphincs_plus.so`) that has to cover the
union of all three.  The Rust `randombytes` is the `rng.c` (DRBG) one — the
`randombytes.c` `/dev/urandom` variant is translated as
`randombytes_urandom` with no `#[no_mangle]`, because the two cannot share the
linker name `randombytes` inside one object.  That matches the `driver`, which
CMake links against `sphincs_core_det`.

## Parity result

`./symdiff.sh` compares the two symbol sets for all 48 feature combinations.

HDR

echo '```'
"$ROOT/symdiff.sh"
echo '```'

cat <<'MID'

## Per-configuration symbol tables

`nm` type letters: `T` = text (function), `R` = read-only data,
`B` = uninitialised data.  "Rust" is ✅ when the Rust `cdylib` for the matching
feature combination exports the same name.

MID

# The core + rng symbol set is identical for every configuration, so tabulate it
# once and then only the per-backend part.
echo "### Configuration-independent symbols (all 48 combinations)"
echo
echo "| symbol | C type | C object | Rust |"
echo "|---|---|---|---|"
comm -12 <(csyms blake simple 128f | awk '{print $1" "$2}') \
         <(csyms sha2 simple 128f | awk '{print $1" "$2}') \
  | while read -r s t; do
      obj=$(nm -D --defined-only "$ROOT/cbuild/blake_simple_128f/app/libsphincs_core_det.so" \
            | awk -v s="$s" 'NF==3 && $3==s {print "libsphincs_core[_det].so"}' | head -1)
      [ -z "$obj" ] && obj="lib<be>.so (+utils.c)"
      ok="❌"; rsyms blake simple 128f | grep -qx "$s" && ok="✅"
      echo "| \`$s\` | $t | $obj | $ok |"
    done
echo

for be in haraka sha2 shake blake; do
  echo "### \`$be\`-only symbols"
  echo
  echo "| symbol | C type | Rust |"
  echo "|---|---|---|"
  comm -23 <(csyms $be simple 128f | awk '{print $1" "$2}') \
           <(comm -12 <(csyms blake simple 128f | awk '{print $1" "$2}') \
                      <(csyms sha2 simple 128f | awk '{print $1" "$2}')) \
    | while read -r s t; do
        ok="❌"; rsyms $be simple 128f | grep -qx "$s" && ok="✅"
        echo "| \`$s\` | $t | $ok |"
      done
  echo
done

cat <<'TAIL'
## Rust-side undefined symbols

`nm -D --undefined-only` on the Rust `cdylib` lists only glibc / libgcc-unwind
imports (`memcpy`, `malloc`, `_Unwind_*`, …) — there is no unresolved
project-level symbol:

TAIL
echo '```'
nm -D --undefined-only "$ROOT/rustlib/libsphincs_plus_blake_simple_128f.so" \
  | awk '{print $2}' | grep -v '^__\?[A-Za-z_]*@GLIBC' \
  | grep -vE '^_(Unwind|ITM|_cxa|_tls|_errno|_gmon)' | sort -u
echo '(everything else is @GLIBC_* / @GCC_*)'
echo '```'
} > "$OUT"
echo "wrote $OUT ($(wc -l < "$OUT") lines)"
